 <article class="kpi"><div class="kpi-label"><?= Auth::isAdmin()?'Cash expected':'Offline sales synced' ?></div><div class="kpi-value"><?= Auth::isAdmin()?money($stats['expected_cash']):number_format($stats['offline_synced']) ?></div><div class="kpi-hint"><?= Auth::isAdmin()?'Across today’s completed sales':'Recorded by the server today' ?></div></article>
