<div class="dashboard-grid"><section class="card dashboard-recent"><div class="dashboard-section-head"><div><div class="section-kicker">Latest activity</div><h2><?= Auth::isAdmin()?'Recent orders':'My recent transactions' ?></h2></div><a href="<?= e(url('sales')) ?>">All sales →</a></div><?php if(!$recent): ?><div class="inline-empty"><b>No transactions yet</b><span>Completed sales will appear here.</span></div><?php else: ?><div class="dashboard-order-list"><?php foreach($recent as $sale): ?><?php [$sl,$sc]=status_badge($sale['status']); ?><a href="<?= e(url('sales/'.$sale['id'])) ?>"><span><b><?= e($sale['sale_number']) ?></b><small><?= e($sale['customer_name']?:'Walk-in customer') ?> · <?= e(strtoupper($sale['channel'])) ?></small></span><span><b><?= money($sale['total']) ?></b><small><?= e(date('h:i A',strtotime($sale['created_at']))) ?> · <?= e(strtoupper($sale['payment_method'])) ?></small></span><span class="badge badge-<?= $sc ?>"><?= e($sl) ?></span></a><?php endforeach; ?></div><?php endif; ?></section>
<aside class="dashboard-side"><?php if(Auth::isAdmin()): ?><section class="card"><div class="dashboard-section-head"><div><div class="section-kicker">Inventory exceptions</div><h2>Low stock</h2></div><a href="<?= e(url('products?stock=low')) ?>">Open inventory →</a></div><?php if(!$lowStock): ?><p class="muted">All active products are above their reorder point.</p><?php else: ?><div class="dashboard-exceptions"><?php foreach($lowStock as $product): ?><a href="<?= e(url('products/'.$product['id'])) ?>"><span><b><?= e($product['name']) ?></b><small><?= e($product['sku']) ?></small></span><strong><?= Product::stockOf($product) ?> / <?= (int)$product['reorder_level'] ?></strong></a><?php endforeach; ?></div><?php endif; ?></section><section class="card"><div class="section-kicker">Audit trail</div><h2>Recent system activity</h2><div class="dashboard-activity"><?php foreach($activity as $event): ?><div><span></span><p><b><?= e(ucwords(str_replace(['.','_'],' ',$event['action']))) ?></b><small><?= e($event['user_name']?:'System') ?> · <?= e(date('d M, h:i A',strtotime($event['created_at']))) ?></small></p></div><?php endforeach; ?></div></section><?php else: ?><section class="card cashier-handoff"><div class="section-kicker">Shift handoff</div><h2>Before you finish</h2><ul><li>Complete or hand off any pending customer return.</li><li>Confirm locally queued offline sales are synced.</li><li>Count the till and close your day.</li></ul><a class="btn btn-primary btn-block" href="<?= e(url('reports/z')) ?>">Start close-of-day</a></section><?php endif; ?></aside></div>
